}

edits.replacement:
function netSeatName(s){
  var r=NET.roster||[], i;
  // v30.xx (cw-p1p2), HIS ORDER (2026-10-18): "there seem to be a lot of inconsistencies between p1 and p2 games, please coordinate them better". The roster
  // keeps the name each save had when the two windows linked, before the party arcade renamed them, so over a head, on the team bar and in the feed one
  // window read a save name or Pillager where the other read Player 2. In the party arcade the two seats are Player 1 and Player 2 in both windows.
  for(i=0;i<r.length;i++) if(r[i].seat===s) return (typeof ARCADE==='object'&&ARCADE&&ARCADE.on&&!ARCADE.solo&&(s===0||s===1))?('Player '+(s+1)):r[i].name;
  return null;
}

check:
{v:'VER',what:'in the party arcade demo both windows call the two seats Player 1 and Player 2 whatever the saves are named (his order of 2026-10-18: p1 and p2 should look and behave the same), so a name over a teammate head, on the team bar and in the feed agree; outside the arcade the roster names stand as they were; a seat outside the party is still nobody',
 run:function(){
   if(typeof netSeatName!=='function'||typeof ARCADE==='undefined'||!ARCADE||typeof NET==='undefined'||!NET) return 'SKIP: this build has no seat names or no party arcade';
   var keep={roster:NET.roster,on:ARCADE.on,solo:ARCADE.solo}, bad=[], a, b, c, d;
   try{
     NET.roster=[{seat:0,name:'ZQX HOST'},{seat:1,name:'ZQX GUEST'},{seat:2,name:'ZQX THIRD'}];
     ARCADE.on=0; ARCADE.solo=0;
     if(netSeatName(0)!=='ZQX HOST'||netSeatName(1)!=='ZQX GUEST'||netSeatName(2)!=='ZQX THIRD') bad.push('control: outside the arcade the roster names do not stand ('+netSeatName(0)+', '+netSeatName(1)+', '+netSeatName(2)+')');
     ARCADE.on=1;
     a=netSeatName(0); b=netSeatName(1); c=netSeatName(2); d=netSeatName(5);
     if(String(a).toLowerCase()!=='player 1') bad.push('in the party arcade seat 0 is called '+a+', not Player 1');
     if(String(b).toLowerCase()!=='player 2') bad.push('in the party arcade seat 1 is called '+b+', not Player 2');
     if(c!=='ZQX THIRD') bad.push('in the party arcade a third seat lost its roster name ('+c+')');
     if(d!==null) bad.push('a seat outside the party has a name: '+d);
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ NET.roster=keep.roster; ARCADE.on=keep.on; ARCADE.solo=keep.solo; }catch(_f){} }
   return bad.length?bad.join('; '):null; }},
